From dde161de5065ef046d6fab92a4ebfa803e381ef5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 22:47:38 +0100
Subject: [PATCH] daemon: add an inhibition type to only keep the display on

Apps could only inhibit idle as a whole, which also blocks locking, and
idle inhibitions stop counting once the screen is locked. Add a display
type that stops the display from turning off, also on the lock screen.

BUG: 369129
---
 daemon/actions/bundled/dpms.cpp               |  6 ++--
 ....kde.Solid.PowerManagement.PolicyAgent.xml |  2 +-
 daemon/powerdevilpolicyagent.cpp              | 28 +++++++++++++++++++
 daemon/powerdevilpolicyagent.h                |  1 +
 4 files changed, 33 insertions(+), 4 deletions(-)

diff --git a/daemon/actions/bundled/dpms.cpp b/daemon/actions/bundled/dpms.cpp
index 2b8ec6e60..1ea107075 100644
--- a/daemon/actions/bundled/dpms.cpp
+++ b/daemon/actions/bundled/dpms.cpp
@@ -44,14 +44,14 @@ DPMS::DPMS(QObject *parent)
     : Action(parent)
     , m_dpms(new KScreen::Dpms)
 {
-    setRequiredPolicies(PowerDevil::PolicyAgent::ChangeScreenSettings);
+    setRequiredPolicies(PowerDevil::PolicyAgent::TurnOffDisplay);

     // Listen to the policy agent
     auto policyAgent = PowerDevil::PolicyAgent::instance();
     connect(policyAgent, &PowerDevil::PolicyAgent::unavailablePoliciesChanged, this, &DPMS::onUnavailablePoliciesChanged);
     connect(policyAgent, &PowerDevil::PolicyAgent::screenLockerActiveChanged, this, &DPMS::onScreenLockerActiveChanged);

-    m_inhibitScreen = policyAgent->unavailablePolicies() & PowerDevil::PolicyAgent::ChangeScreenSettings;
+    m_inhibitScreen = policyAgent->unavailablePolicies() & PowerDevil::PolicyAgent::TurnOffDisplay;

     connect(core()->suspendController(), &SuspendController::aboutToSuspend, this, &DPMS::onAboutToSuspend);
     connect(core()->suspendController(), &SuspendController::resumeFromSuspend, this, &DPMS::onResumeFromSuspend);
@@ -187,7 +187,7 @@ void DPMS::onProfileUnload()

 void DPMS::onUnavailablePoliciesChanged(PowerDevil::PolicyAgent::RequiredPolicies policies)
 {
-    m_inhibitScreen = policies & PowerDevil::PolicyAgent::ChangeScreenSettings;
+    m_inhibitScreen = policies & PowerDevil::PolicyAgent::TurnOffDisplay;
 }

 void DPMS::registerStandardIdleTimeout()
diff --git a/daemon/dbus/org.kde.Solid.PowerManagement.PolicyAgent.xml b/daemon/dbus/org.kde.Solid.PowerManagement.PolicyAgent.xml
index db71ca82e..bdbc69a6d 100644
--- a/daemon/dbus/org.kde.Solid.PowerManagement.PolicyAgent.xml
+++ b/daemon/dbus/org.kde.Solid.PowerManagement.PolicyAgent.xml
@@ -8,7 +8,7 @@
         <doc:para>
           The format of this structure roughly follows that of org.freedesktop.login1 inhibitors, but the returned list does not necessarily return the same elements. It may be missing some (e.g. delay inhibitors, the service's own inhibitors, unsupported "what" policies) or may include additional elements that did not pass through the org.freedesktop.login1 interface in the first place.
           <doc:list>
-            <doc:item>"what" is one or more of "sleep", "idle", separated by colons, for inhibiting suspend/hibernate or automatic dimming/screen-locking on idle, respectively. More types may be supported in the future.</doc:item>
+            <doc:item>"what" is one or more of "sleep", "idle", "display", separated by colons, for inhibiting suspend/hibernate, automatic dimming/screen-locking on idle, or only turning off the display (also while the screen is locked), respectively. More types may be supported in the future.</doc:item>
             <doc:item>"who" identifies the application taking the lock.</doc:item>
             <doc:item>"why" identifies the reason why the lock is taken.</doc:item>
             <doc:item>"mode" is either "block" or "delay", which identifies whether an inhibition shall be considered mandatory or whether it should just delay the operation to a certain maximum time.</doc:item>
diff --git a/daemon/powerdevilpolicyagent.cpp b/daemon/powerdevilpolicyagent.cpp
index 8ed1edc60..c48759f17 100644
--- a/daemon/powerdevilpolicyagent.cpp
+++ b/daemon/powerdevilpolicyagent.cpp
@@ -432,6 +432,9 @@ PolicyAgent::RequiredPolicies PolicyAgent::policiesInLogindWhat(const QString &w
     if (types.contains("idle"_L1)) {
         policies |= ChangeScreenSettings;
     }
+    if (types.contains("display"_L1)) {
+        policies |= TurnOffDisplay;
+    }
     return policies;
 }

@@ -444,6 +447,9 @@ QString PolicyAgent::logindWhatForPolicies(PolicyAgent::RequiredPolicies policie
     if (policies & ChangeScreenSettings) {
         what.append(u"idle"_s);
     }
+    if (policies & TurnOffDisplay) {
+        what.append(u"display"_s);
+    }
     return what.join(":"_L1);
 }

@@ -534,6 +540,10 @@ PolicyAgent::RequiredPolicies PolicyAgent::unavailablePolicies()
     if (!m_screenLockerActive && !m_typesToCookie[ChangeScreenSettings].isEmpty()) {
         retpolicies |= ChangeScreenSettings;
     }
+    // unlike ChangeScreenSettings, this keeps the screen on even when locked
+    if ((retpolicies & ChangeScreenSettings) || !m_typesToCookie[TurnOffDisplay].isEmpty()) {
+        retpolicies |= TurnOffDisplay;
+    }
     if (!m_typesToCookie[InterruptSession].isEmpty()) {
         retpolicies |= InterruptSession;
     }
@@ -579,6 +589,11 @@ PolicyAgent::RequiredPolicies PolicyAgent::requirePolicyCheck(PolicyAgent::Requi
             retpolicies |= ChangeScreenSettings;
         }
     }
+    if (policies & TurnOffDisplay) {
+        if (!m_typesToCookie[ChangeScreenSettings].isEmpty() || !m_typesToCookie[TurnOffDisplay].isEmpty()) {
+            retpolicies |= TurnOffDisplay;
+        }
+    }
     if (policies & InterruptSession) {
         if (m_sessionIsBeingInterrupted || !m_typesToCookie[InterruptSession].isEmpty()) {
             retpolicies |= InterruptSession;
@@ -715,6 +730,13 @@ void PolicyAgent::addInhibitionTypeHelper(uint cookie, PolicyAgent::RequiredPoli
         m_typesToCookie[ChangeScreenSettings].append(cookie);
         types |= InterruptSession; // implied by ChangeScreenSettings
     }
+    if (types & TurnOffDisplay) {
+        qCDebug(POWERDEVIL) << "Added turn off display";
+        if (m_typesToCookie[TurnOffDisplay].isEmpty()) {
+            notify = true;
+        }
+        m_typesToCookie[TurnOffDisplay].append(cookie);
+    }
     if (types & InterruptSession) {
         // Check if we have to notify
         qCDebug(POWERDEVIL) << "Added interrupt session";
@@ -778,6 +800,12 @@ void PolicyAgent::ReleaseInhibition(uint cookie, bool retainCookie)
             notify = true;
         }
     }
+    if (m_typesToCookie[TurnOffDisplay].contains(cookie)) {
+        m_typesToCookie[TurnOffDisplay].removeOne(cookie);
+        if (m_typesToCookie[TurnOffDisplay].isEmpty()) {
+            notify = true;
+        }
+    }
     if (m_typesToCookie[InterruptSession].contains(cookie)) {
         m_typesToCookie[InterruptSession].removeOne(cookie);
         // Check if we have to notify
diff --git a/daemon/powerdevilpolicyagent.h b/daemon/powerdevilpolicyagent.h
index 41c8b45d9..d5019594c 100644
--- a/daemon/powerdevilpolicyagent.h
+++ b/daemon/powerdevilpolicyagent.h
@@ -84,6 +84,7 @@ public:
         None = 0,
         InterruptSession = 1,
         ChangeScreenSettings = 4,
+        TurnOffDisplay = 8,
     };
     Q_DECLARE_FLAGS(RequiredPolicies, RequiredPolicy)

